console.log(JSON.stringify(variants, null, 2));

// Compatible products
const compat = JSON.parse(product.compatible_with_json);
if (compat.length > 0) {
  const placeholders = compat.map(() => '?').join(',');
  const compatProducts = db.prepare('SELECT product_id, name, price FROM products WHERE product_id IN (' + placeholders + ')').all(...compat);
  console.log('\n=== Compatible Products ===');
  console.log(JSON.stringify(compatProducts, null, 2));
}
"

